  // stale custom port can't make the initial connect dial a dead bridge.
  try {
    const v = getSetting(SETTING_BRIDGE);
    if (typeof v === "string" && v.trim()) return v.trim();
  } catch {
    // settings not ready yet — fall through to the default.
  }
