    const id = resolveUnsavedInstanceUuid({
      objectUuid,
      embeddedId,
      forkActive: _loadGraphDataForkInstalled,
    });
    setWorkflowObjectUuid(identityObject, id);
    rememberWorkflowUuidOwner(id, identityObject);
